    "cache_path" TEXT,
    "last_updated" TEXT,
    "last_accessed" TEXT,
    "cache_size_bytes" INTEGER,
    "hit_count" INTEGER,
    "miss_count" INTEGER,
    "hit_ratio" REAL,
    "invalidation_rules" TEXT,
    -- JSON-encoded
    "backing_store" TEXT CHECK ("backing_store" IN ('file', 'memory', 'sqlite')),
    "encryption_enabled" INTEGER,
    "compression_enabled" INTEGER
);

CREATE TABLE IF NOT EXISTS trigger (
    "trigger_type" TEXT NOT NULL,
    "trigger_source" TEXT NOT NULL,
    "trigger_action" TEXT NOT NULL,
    "schedule" TEXT,
    "dependencies" TEXT,
    -- JSON-encoded
    "health_check" TEXT,
    -- JSON-encoded
    "interval_seconds" REAL,
    "retry_policy" TEXT
    -- JSON-encoded
);

CREATE TABLE IF NOT EXISTS work_packet (
    "packet_id" TEXT NOT NULL,
    "schema_version" TEXT NOT NULL,
    "blueprint_ref" TEXT NOT NULL,
    "wave" TEXT NOT NULL,
    "bet_id" TEXT NOT NULL,
    "strategic_outcome" TEXT NOT NULL,
    "objective" TEXT NOT NULL,
    "why_now" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "authority" TEXT NOT NULL,
    -- JSON-encoded
    "scope" TEXT NOT NULL,
    -- JSON-encoded
    "dependencies" TEXT NOT NULL,
    -- JSON-encoded
    "acceptance" TEXT NOT NULL,
    -- JSON-encoded
    "budgets" TEXT NOT NULL,
    -- JSON-encoded
    "rollback" TEXT NOT NULL,
    -- JSON-encoded
    "circuit_breaker" TEXT NOT NULL,
    -- JSON-encoded
    "assignment" TEXT NOT NULL,
    -- JSON-encoded
    "description" TEXT,
    "tags" TEXT
    -- JSON-encoded
);

CREATE TABLE IF NOT EXISTS workflow (
    "workflow_name" TEXT NOT NULL,
    "steps" TEXT NOT NULL,
    -- JSON-encoded
    "trigger" TEXT,
    "agent" TEXT,
    "timeout" TEXT,
    "domain" TEXT,
    "subtype" TEXT,
    "bos_uri" TEXT,
    "cross_layer" TEXT,
    -- JSON-encoded
    "execution" TEXT,
    -- JSON-encoded
    "relations" TEXT,
    -- JSON-encoded
    "sla" TEXT,
    -- JSON-encoded
    "tags" TEXT,
    -- JSON-encoded
    "layer" TEXT,
    "maintained_by" TEXT,
    "last_reviewed" TEXT
);

